let currentMetric = 'tokens'; // 'tokens' or 'users'
let activeBar = null;

// ─── RENDER TOP MODELS CHART ───
function renderTopModelsChart() {
  const chartEl = document.getElementById('top-models-chart');
  const axis = document.getElementById('chart-axis');
  const bars = document.getElementById('chart-bars');
  if (!axis || !bars) return;

  const data = currentMetric === 'tokens' ? usageData : usersData;
  const maxTotal = Math.max(...data.map(d => d.segments.reduce((s, seg) => s + seg.value, 0)));

  axis.innerHTML = '';
  bars.innerHTML = '';

  data.forEach((day, i) => {
    const total = day.segments.reduce((s, seg) => s + seg.value, 0);
    const showLabel = i % 4 === 0 || i === data.length - 1;

    // Axis label
    const axisDiv = document.createElement('div');
    if (!showLabel) axisDiv.setAttribute('data-label-hidden', 'true');
    axisDiv.innerHTML = `<span data-slot="axis-label"><span data-slot="axis-date-mobile">${day.date}</span></span>`;
    axis.appendChild(axisDiv);

    // Bar
    const barDiv = document.createElement('div');
    barDiv.setAttribute('data-slot', 'top-models-bar');
    barDiv.setAttribute('tabindex', '0');
    barDiv.setAttribute('role', 'button');
    barDiv.setAttribute('aria-label', `${day.date}: ${currentMetric === 'tokens' ? total.toFixed(1) + 'T' : formatNumber(total) + ' users'}`);

    const heightPct = (total / maxTotal * 100).toFixed(1);
    const stack = document.createElement('div');
    stack.setAttribute('data-slot', 'top-models-stack');
    stack.style.height = heightPct + '%';

    // Build segments (filter out zero values)
    const segs = day.segments.filter(s => s.value > 0);
    segs.forEach(seg => {
      const pct = (seg.value / total * 100);
      const el = document.createElement('i');
      el.style.flexGrow = pct.toString();
      el.style.background = MODEL_COLORS[seg.model] || '#94a3b8';
      el.title = `${seg.model}: ${currentMetric === 'tokens' ? seg.value.toFixed(2) + 'T' : formatNumber(seg.value)}`;
      stack.appendChild(el);
    });

    // Tooltip on hover
    barDiv.addEventListener('mouseenter', () => showChartTooltip(barDiv, day, total, 'top-models'));
    barDiv.addEventListener('mouseleave', () => hideChartTooltip('top-models'));

    barDiv.appendChild(stack);
    bars.appendChild(barDiv);
  });
}

// ─── CHART TOOLTIP ───
function showChartTooltip(barEl, day, total, section) {
  let tooltip = document.querySelector(`[data-section="${section}"] [data-component="chart-tooltip"]`);
  if (!tooltip) {
    tooltip = document.createElement('div');
    tooltip.setAttribute('data-component', 'chart-tooltip');
    const sectionEl = document.getElementById(section);
    if (sectionEl) sectionEl.appendChild(tooltip);
    else return;
  }

  const segs = day.segments.filter(s => s.value > 0).sort((a,b) => b.value - a.value);
  let html = `<strong>${day.date}</strong><span>${currentMetric === 'tokens' ? total.toFixed(2) + 'T total' : formatNumber(total) + ' users'}</span>`;
  html += '<div data-slot="tooltip-divider"></div>';
  segs.forEach(seg => {
    const color = MODEL_COLORS[seg.model] || '#94a3b8';
    const pct = (seg.value / total * 100).toFixed(1);
    const valStr = currentMetric === 'tokens' ? seg.value.toFixed(2) + 'T' : formatNumber(seg.value);
    html += `<p><span data-slot="tooltip-label"><i style="background:${color}"></i><span data-slot="tooltip-name">${seg.model}</span></span><b>${valStr}</b></p>`;
  });
  tooltip.innerHTML = html;
  tooltip.style.display = 'flex';

  // Position
  const rect = barEl.getBoundingClientRect();
  const parent = barEl.closest('[data-section]').getBoundingClientRect();
  const midX = rect.left - parent.left + rect.width / 2;
  if (midX > parent.width / 2) {
    tooltip.style.left = 'auto';
    tooltip.style.right = (parent.width - (rect.left - parent.left)) + 'px';
    tooltip.setAttribute('data-placement', 'left');
  } else {
    tooltip.style.right = 'auto';
    tooltip.style.left = (rect.right - parent.left) + 'px';
    tooltip.setAttribute('data-placement', 'right');
  }
}

function hideChartTooltip(section) {
  const tooltip = document.querySelector(`[data-section="${section}"] [data-component="chart-tooltip"]`);
  if (tooltip) tooltip.style.display = 'none';
}

// ─── RENDER LEADERBOARD ───
function renderLeaderboard() {
  const grid = document.getElementById('leaderboard-grid');
  if (!grid) return;

  const featured = leaderboard.slice(0, 3);
  const compact = leaderboard.slice(3);

  let html = '<div data-slot="leaderboard-featured">';
  featured.forEach(item => {
    const deltaStr = item.change !== null
      ? `<span data-slot="delta" ${item.change < 0 ? 'data-negative="true"' : ''}>${item.change > 0 ? '+' : ''}${item.change}%</span>`
      : '';
    html += `
      <div data-component="leader-card" data-size="featured">
        <span data-slot="rank">#${item.rank}</span>
        <div data-slot="leader-body">
          <span data-slot="leader-avatar">${item.author ? item.author.charAt(0) : '?'}</span>
          <div data-slot="leader-copy">
            <strong>${item.model}</strong>
            <div>
              <span>${formatTokens(item.tokens)}</span>
              ${deltaStr}
            </div>
          </div>
        </div>
      </div>`;
  });
  html += '</div><div data-slot="leaderboard-pattern"></div><div data-slot="leaderboard-compact">';

  compact.forEach(item => {
    const deltaStr = item.change !== null
      ? `<span data-slot="delta" ${item.change < 0 ? 'data-negative="true"' : ''}>${item.change > 0 ? '+' : ''}${item.change}%</span>`
      : '<span data-slot="delta">NEW</span>';
    html += `
      <div data-component="leader-card" data-size="compact">
        <div data-slot="leader-body">
          <span data-slot="leader-avatar">${item.rank}</span>
          <div data-slot="leader-copy">
            <strong>${item.model}</strong>
            <div>
              <span>${formatTokens(item.tokens)}</span>
              ${deltaStr}
            </div>
          </div>
        </div>
      </div>`;
  });
  html += '</div>';
  grid.innerHTML = html;
}

// ─── RENDER SESSION COST ───
function renderSessionCost() {
  const table = document.getElementById('session-cost-table');
  if (!table) return;
  let html = '<div class="table-head"><span></span><span>Model</span><span style="text-align:right">Cost</span><span style="text-align:right">Tokens</span></div>';
  sessionCost.forEach((item, i) => {
    html += `<div class="table-row">
      <span class="rank">${i + 1}</span>
      <span class="name">${item.model}</span>
      <span class="value">$${item.cost.toFixed(4)}</span>
      <span class="secondary">${formatNumber(item.tokens)}</span>
    </div>`;
  });
  table.innerHTML = html;
}

